const http = require("https");

const options = {
  "method": "GET",
  "hostname": "api.customer.io",
  "port": null,
  "path": "/v1/campaigns/{campaign_id}/metrics?start=1735718400&end=1735804800&res=days&version=2",
  "headers": {}
};

const req = http.request(options, function (res) {
  const chunks = [];

  res.on("data", function (chunk) {
    chunks.push(chunk);
  });

  res.on("end", function () {
    const body = Buffer.concat(chunks);
    console.log(body.toString());
  });
});

req.end();

